--
-- Table structure for table `motherboard`
--

DROP TABLE IF EXISTS `motherboard`;
CREATE TABLE IF NOT EXISTS `motherboard` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nama` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `socket_id` int NOT NULL,
  `form_factor` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ram_type_id` int NOT NULL,
  `ram_slots` int DEFAULT NULL,
  `max_ram_gb` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `socket_id` (`socket_id`),
  KEY `ram_type_id` (`ram_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1024 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

