--
-- Table structure for table `ram`
--

DROP TABLE IF EXISTS `ram`;
CREATE TABLE IF NOT EXISTS `ram` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nama` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ram_type_id` int NOT NULL,
  `jumlah_keping` int DEFAULT NULL,
  `kapasitas_gb` int DEFAULT NULL COMMENT 'total',
  `speed_mhz` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ram_type_id` (`ram_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4096 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

